      or: 'ସମସ୍ତ ପ୍ରମୁଖ ଗ୍ରହ ରାହୁ ଏବଂ କେତୁଙ୍କର ଏକା ପାଖରେ ଅବସ୍ଥିତ। କାଳସର୍ପ ଯୋଗର ପ୍ରଭାବ ରହିପାରେ।',
      as: 'সকলো প্ৰধান গ্ৰহ ৰাহু আৰু কেতুৰ একেফালে অৱস্থিত। কালসৰ্প যোগৰ প্ৰভাৱ থাকিব পাৰে।',
