      "ta": "2, 5, 9 மற்றும் 11 ஆம் பாவங்களின் அதிபதிகளின் தொடர்பு பெரும் செல்வத்தையும் செழிப்பையும் தருகிறது.",
      "te": "2, 5, 9 మరియు 11వ స్థానాల అధిపతుల సంబంధం విపరీతమైన సంపద మరియు శ్రేయస్సును ప్రసాదిస్తుంది.",
      "kn": "2, 5, 9 ಮತ್ತು 11ನೇ ಮನೆಗಳ ಅಧಿಪತಿಗಳ ಸಂಬಂಧವು ಅಪಾರ ಸಂಪತ್ತು ಮತ್ತು ಸಮೃದ್ಧಿಯನ್ನು ತರುತ್ತದೆ.",
      "ml": "2, 5, 9, 11 എന്നീ ഭാവങ്ങളുടെ അധിപന്മാർ തമ്മിലുള്ള ബന്ധം വലിയ സമ്പത്തും ഐശ്വര്യവും നൽകുന്നു.",
      "pa": "2, 5, 9 ਅਤੇ 11ਵੇਂ ਘਰ ਦੇ ਮਾਲਕਾਂ ਦਾ ਆਪਸੀ ਸਬੰਧ ਭਰਪੂਰ ਧਨ-ਦੌਲਤ ਅਤੇ ਖੁਸ਼ਹਾਲੀ ਦਿੰਦਾ ਹੈ।",
      "or": "୨, ୫, ୯ ଏବଂ ୧୧ଶ ଭାବାଧିପତିଙ୍କ ସମ୍ପର୍କରୁ ବିପୁଳ ଧନସମ୍ପତ୍ତି ପ୍ରାପ୍ତ ହୁଏ।",
      "as": "২, ৫, ৯ আৰু ১১তম স্থানাধিপতিসকলৰ সম্পৰ্কে বিপুল ধন আৰু সমৃদ্ধি আনি দিয়ে।",
      "ur": "دوسرے، پانچویں، نویں اور گیارہویں گھر کے حاکموں کا تعلق بے پناہ دولت اور کشادگی لاتا ہے۔"
