      "kn": "6, 8 ಅಥವಾ 12ನೇ ಮನೆಗಳ ಅಧಿಪತಿಗಳ ಸಂಬಂಧದಿಂದ ಅನಿರೀಕ್ಷಿತ ಯಶಸ್ಸು ಮತ್ತು ಸವಾಲುಗಳ ಜಯ ಸಾಧ್ಯವಾಗುತ್ತದೆ.",
      "ml": "6, 8, 12 ഭാവങ്ങളുടെ അധിപന്മാർ ഒന്നിക്കുമ്പോൾ പ്രതിസന്ധികളെ മറികടന്ന് അപ്രതീക്ഷിത വിജയം ലഭിക്കുന്നു.",
