      "ta": "குழந்தைகள், படைப்பாற்றல், வம்ச வளர்ச்சி மற்றும் பரம்பரை.",
      "te": "సంతానం, సృజనాత్మకత, వంశవృద్ధి మరియు వారసత్వం.",
      "kn": "ಸಂತಾನ, ಸೃಜನಶೀಲತೆ, ವಂಶೋದ್ಧಾರ ಮತ್ತು ಪರಂಪರೆ.",
