/**
 * Helper to resolve localized text falling back gracefully: lang -> hi -> mr -> en
 */
function resolveLang(dict, lang) {
  if (!dict) return '';
  return dict[lang] || dict['hi'] || dict['mr'] || dict['en'] || Object.values(dict)[0] || '';
}

